import{_ as a,C as r,o as l,c as d,a2 as i,E as s,j as t,a as o}from"./chunks/framework.CGSzHL4z.js";const w=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1792705540000}'),h={name:"guide/installation.md"};function c(u,e,p,g,m,f){const n=r("Screenshot");return l(),d("div",null,[e[0]||(e[0]=i('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="the-plugin" tabindex="-1">The plugin <a class="header-anchor" href="#the-plugin" aria-label="Permalink to &quot;The plugin&quot;">​</a></h2><p>Get AcesMotion from the Creator Store: <a href="https://create.roblox.com/store/asset/108839243533841" target="_blank" rel="noreferrer">https://create.roblox.com/store/asset/108839243533841</a>. Click <strong>Get</strong>, then open Studio&#39;s <strong>Plugins</strong> tab. When a new version is out, Studio&#39;s <strong>Manage Plugins</strong> shows an <strong>Update</strong> button, and AcesMotion tells you too (Settings &gt; Versions).</p><h3 id="how-to-open-it" tabindex="-1">How to open it <a class="header-anchor" href="#how-to-open-it" aria-label="Permalink to &quot;How to open it&quot;">​</a></h3><ul><li>The plugin adds one toolbar named <strong>AcesMotion</strong> with three buttons. <strong>AcesMotion</strong> turns it on or off. <strong>Create reference</strong> makes a reference to the scene selected in the Explorer (see References), without opening any window. <strong>References</strong> opens or closes the References window, and is lit while it&#39;s open.</li><li>Click the button: the Timeline, Hub and the Inspector open, and the scene that was open last reopens. Click it again: every AcesMotion window closes. The button shows as on (lit) while any AcesMotion window is open, so a click with only the Inspector open closes it too.</li><li><strong>The Timeline is the switch for the scene.</strong> Hiding the Timeline any way (its own close button, the toolbar button) closes the open scene and puts every stand-in back at rest. Showing the Timeline again reopens that scene. Resetting the window layout does not close the scene.</li><li>The other windows open from the Timeline&#39;s View &gt; Windows menu: Hub, Inspector, Settings, References. Settings also opens from the Scene menu&#39;s Settings item, from the Settings button on the empty Timeline, and from any &quot;... settings...&quot; menu item. The shortcut &quot;Open settings&quot; has no default key.</li><li>First placement: the Timeline docks at the bottom, Hub and the Inspector dock on the right (the Inspector opens under Hub), and Settings floats. After that Studio remembers where you put each window, docked or floating, its size included, and keeps it when AcesMotion updates or reloads. <strong>View &gt; Windows &gt; Reset window layout</strong> (shortcut &quot;Reset window layout&quot;, no default key) puts them back at Studio&#39;s first placement.</li><li>Window titles read &quot;AcesMotion 0.2.0 · Timeline&quot;, &quot;... · Hub&quot;, &quot;... · Inspector&quot;, &quot;... · Settings&quot;.</li></ul>',5)),s(n,{name:"toolbar-button",caption:"The AcesMotion toolbar button."}),e[1]||(e[1]=i('<h2 id="the-runtime" tabindex="-1">The runtime <a class="header-anchor" href="#the-runtime" aria-label="Permalink to &quot;The runtime&quot;">​</a></h2><p>Games play scenes with the runtime, a ModuleScript the plugin writes into your place.</p><h3 id="install-and-layout" tabindex="-1">Install and layout <a class="header-anchor" href="#install-and-layout" aria-label="Permalink to &quot;Install and layout&quot;">​</a></h3><p>The runtime is one ModuleScript, <code>ReplicatedStorage.AcesMotion</code>, written into your place by the plugin itself.</p><h4 id="install-or-update" tabindex="-1">Install or update <a class="header-anchor" href="#install-or-update" aria-label="Permalink to &quot;Install or update&quot;">​</a></h4><ul><li>Settings &gt; About &gt; <strong>Install runtime</strong> writes the module. <strong>Update runtime</strong> sits in the same place and on the Timeline&#39;s &quot;Update runtime&quot; banner.</li><li>The module is a ModuleScript holding <code>Engine</code>, <code>Runtime</code> and <code>Packages</code> (Signal, Trove), with an <code>AcesMotion_Version</code> attribute. Its source is a short note, the MIT licence, and a <code>require</code>.</li><li>Updating keeps the root and replaces its children. Scenes are untouched, and the whole update is one undo step.</li><li>A place whose runtime is synced from files refuses the button.</li><li>About shows &quot;Not installed&quot;, &quot;0.2.0 (up to date)&quot;, &quot;(older, update it)&quot; or &quot;(newer than this plugin)&quot;.</li></ul><h4 id="require-it" tabindex="-1">Require it <a class="header-anchor" href="#require-it" aria-label="Permalink to &quot;Require it&quot;">​</a></h4><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AcesMotion </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(game.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ReplicatedStorage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AcesMotion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><ul><li><strong>Every client requires it once</strong> to receive <code>PlayForAll</code>. A LocalScript in StarterPlayerScripts is enough.</li><li>Requiring it on the server is <strong>optional</strong>. Only <code>PlayForAll</code> and a server <code>Play</code> need it there, so a client-only game never touches the server.</li></ul><h4 id="where-scenes-are-found" tabindex="-1">Where scenes are found <a class="header-anchor" href="#where-scenes-are-found" aria-label="Permalink to &quot;Where scenes are found&quot;">​</a></h4><ul><li>By name, in <code>ReplicatedStorage.AcesMotionScenes</code>, then in every folder given to <code>RegisterFolder</code>. Subfolders count too, shallowest first, never inside a scene.</li><li>A reference finds its scene by id instead: in those folders and in every folder tagged <code>AcesMotionScene</code>, wherever it is, including scenes that stream in later.</li><li>If two scenes share an id (one was copied in the Explorer), the runtime warns once and plays the first it finds.</li><li>A client can only play scenes it can see (not ServerStorage). Register the folder on every side that plays by name.</li></ul><h4 id="custom-modules" tabindex="-1">Custom modules <a class="header-anchor" href="#custom-modules" aria-label="Permalink to &quot;Custom modules&quot;">​</a></h4><p>Tagged ModuleScripts register by module name.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Tag</th><th>Where</th><th>If the game can&#39;t find it</th></tr></thead><tbody><tr><td><strong>Custom generators</strong></td><td><code>AcesMotionGenerator</code></td><td>Anywhere both sides can require</td><td>Adds nothing (warned once).</td></tr><tr><td><strong>Custom constraints</strong></td><td><code>AcesMotionConstraint</code></td><td>Anywhere both sides can require</td><td>Does nothing. One that doesn&#39;t load warns once.</td></tr><tr><td><strong>Custom actions</strong></td><td><code>AcesMotionAction</code></td><td>Anywhere</td><td></td></tr></tbody></table><ul><li>Generators and constraints keep working after a rename.</li><li>An action module may return just a function (an instant action).</li><li><code>RegisterAction</code> also works for action blocks with that <code>Action</code>. They run only where the scene plays in full.</li><li><strong>Modifiers</strong> live in <code>ReplicatedStorage.AcesMotionModifiers</code> (stored; not evaluated yet).</li></ul><h4 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h4><ul><li><code>AcesMotion.Version</code> is the release version.</li><li><code>AcesMotion.FormatVersion</code> is the newest scene format it reads. A scene saved in a newer format is refused by name.</li></ul>',17)),s(n,{name:"install-runtime",caption:"Settings > About: the runtime in this place and the button that installs or updates it."}),e[2]||(e[2]=t("p",null,[o("The full API, with every function, option and type, is in the "),t("a",{href:"/AcesMotion-docs/api/"},"Runtime API"),o(".")],-1)),e[3]||(e[3]=t("p",null,[t("strong",null,"Next:"),o(),t("a",{href:"./tour"},"A quick tour"),o(" of the windows.")],-1))])}const y=a(h,[["render",c]]);export{w as __pageData,y as default};
